/* @lc app=leetcode id=3752 lang=kotlin */ class Solution { fun lexSmallestNegatedPerm(n: Int, target: Long): IntArray = (n.toLong() * (n + 1) / 2).let { S -> if (Math.abs(target) > S || (S - target) % 2 != 0L) IntArray(0) else ((S - target) / 2).let { N -> ArrayList<Int>().let { neg -> (n downTo 1).fold(N) { rem, v -> if (v <= rem) neg.add(v).let { rem - v } else rem }.let { neg.toHashSet().let { ns -> (neg.map { -it } + (1..n).filter { it !in ns }).toIntArray() } } } } } }